// The terminal WebView's page: xterm.js (inlined, see
// scripts/gen-xterm-vendor.mjs) plus a small bridge. React Native owns the
// PTY conversation (create / history / data / write / resize, through
// client.api); the page only renders and collects input.
//
// Page → RN (postMessage, JSON):
//   ready {cols, rows}      fitted and ready for output
//   resize {cols, rows}     fitted to a new size (deduped)
//   ack                     the last write finished parsing (backpressure)
//   data {data}             xterm-generated bytes (query replies, paste)
//   text {text} / key {key} typed on the soft keyboard
//   focus {on}              the input gained / lost focus (keyboard up)
//   scrolled {atBottom}
// RN → page (injectJavaScript): window.ness.{write, focus, blur, paste,
//   scrollToBottom}.
//
// Input mirrors the web client's MobileTerminal: a hidden textarea of our
// own takes the soft keyboard (xterm's own textarea is never focused —
// iOS autocorrect and composition misbehave in it), and a transparent
// layer over xterm turns one-finger drags into scrollback scrolling
// (xterm has no touch scrolling of its own) and taps into focus.
import { FIT_JS, XTERM_CSS, XTERM_JS } from './xterm-vendor.generated'

export interface TerminalPageOptions {
  theme: Record<string, string>
  fontSize: number
  fontFamily: string
}

const BRIDGE = String.raw`
(function () {
  var opts = window.__NESS_OPTS;
  var post = function (m) { window.ReactNativeWebView.postMessage(JSON.stringify(m)); };

  // Same as XTerminal's sanitizeTerminalData on touch devices: alt-screen
  // has no scrollback and mouse tracking turns pans into mouse reports the
  // TUI discards, so both would leave Claude Code / vim unscrollable.
  var TUI_UNFRIENDLY_MODES = /\u001b\[\?(?:47|1000|1002|1003|1005|1006|1015|1047|1049)[hl]/g;
  var textEmoji = typeof CSS !== 'undefined' && CSS.supports && CSS.supports('font-variant-emoji', 'text');
  var sanitize = function (s) {
    s = s.replace(TUI_UNFRIENDLY_MODES, '');
    if (!textEmoji) s = s.replace(/\u23FA/g, '\u25CF');
    return s;
  };

  var term = new Terminal({
    fontSize: opts.fontSize,
    fontFamily: opts.fontFamily,
    cursorBlink: true,
    cursorStyle: 'bar',
    allowProposedApi: true,
    scrollback: 5000,
    theme: opts.theme
  });
  var fit = new FitAddon.FitAddon();
  term.loadAddon(fit);
  var host = document.getElementById('term');
  term.open(host);
  if (term.textarea) {
    term.textarea.setAttribute('tabindex', '-1');
    term.textarea.setAttribute('readonly', 'readonly');
  }
  term.onData(function (d) { post({ t: 'data', data: d }); });

  var lastCols = -1, lastRows = -1;
  var refit = function (initial) {
    if (host.clientWidth < 20 || host.clientHeight < 20) return;
    try { fit.fit(); } catch (e) { return; }
    if (term.cols === lastCols && term.rows === lastRows && !initial) return;
    lastCols = term.cols; lastRows = term.rows;
    post({ t: initial ? 'ready' : 'resize', cols: term.cols, rows: term.rows });
  };
  var readySent = false;
  var tryReady = function () {
    if (readySent) { refit(false); return; }
    if (host.clientWidth < 20 || host.clientHeight < 20) return;
    readySent = true;
    refit(true);
  };
  new ResizeObserver(function () { requestAnimationFrame(tryReady); }).observe(host);
  // Fonts settle a beat after load and change the cell size.
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(function () { tryReady(); });

  var wasAtBottom = true;
  var reportScroll = function () {
    var b = term.buffer.active;
    var atBottom = b.viewportY >= b.baseY;
    if (atBottom !== wasAtBottom) { wasAtBottom = atBottom; post({ t: 'scrolled', atBottom: atBottom }); }
  };
  term.onScroll(reportScroll);

  // ---- input ------------------------------------------------------------
  var input = document.getElementById('input');
  var composing = false;
  var KEYS = { Enter: 1, Backspace: 1, Tab: 1, Escape: 1, ArrowUp: 1, ArrowDown: 1, ArrowLeft: 1, ArrowRight: 1, Home: 1, End: 1 };
  input.addEventListener('input', function () {
    if (composing) return;
    var v = input.value;
    if (!v) return;
    input.value = '';
    post({ t: 'text', text: v });
  });
  input.addEventListener('keydown', function (e) {
    if (composing) return;
    if (KEYS[e.key]) { e.preventDefault(); post({ t: 'key', key: e.key }); }
  });
  input.addEventListener('compositionstart', function () { composing = true; });
  input.addEventListener('compositionend', function () {
    composing = false;
    var v = input.value;
    if (v) { input.value = ''; post({ t: 'text', text: v }); }
  });
  // The iOS edit menu's Paste: through term.paste so bracketed-paste mode
  // is honoured exactly as on desktop.
  input.addEventListener('paste', function (e) {
    var text = e.clipboardData && e.clipboardData.getData('text/plain');
    if (!text) return;
    e.preventDefault();
    term.paste(text);
  });
  input.addEventListener('focus', function () { post({ t: 'focus', on: true }); });
  input.addEventListener('blur', function () { post({ t: 'focus', on: false }); });

  // ---- touch: drag scrolls (with momentum), tap focuses ------------------
  var layer = document.getElementById('touch');
  var lastY = null, accum = 0, dragged = false, vel = 0, lastT = 0, raf = 0;
  var lineH = function () { return host.clientHeight / Math.max(1, term.rows); };
  var scrollPx = function (dy) {
    accum += dy;
    var lines = Math.trunc(accum / lineH());
    if (lines) { accum -= lines * lineH(); term.scrollLines(-lines); reportScroll(); }
  };
  layer.addEventListener('touchstart', function (e) {
    cancelAnimationFrame(raf);
    if (e.touches.length !== 1) { lastY = null; return; }
    lastY = e.touches[0].clientY; lastT = e.timeStamp; accum = 0; vel = 0; dragged = false;
  }, { passive: true });
  layer.addEventListener('touchmove', function (e) {
    e.preventDefault();
    if (lastY === null || e.touches.length !== 1) return;
    var y = e.touches[0].clientY, dy = y - lastY, dt = Math.max(1, e.timeStamp - lastT);
    lastY = y; lastT = e.timeStamp;
    vel = 0.8 * (dy / dt) + 0.2 * vel;
    if (Math.abs(dy) > 0 || dragged) { if (!dragged && Math.abs(accum + dy) > 4) dragged = true; scrollPx(dy); }
  }, { passive: false });
  var end = function () {
    if (lastY === null) return;
    lastY = null;
    if (!dragged) { input.focus({ preventScroll: true }); return; }
    // Momentum: px/ms, decaying per frame, like a native scroll view.
    var v = vel * 16;
    var step = function () {
      if (Math.abs(v) < 0.5) return;
      scrollPx(v); v *= 0.94;
      raf = requestAnimationFrame(step);
    };
    if (Math.abs(v) > 2) raf = requestAnimationFrame(step);
  };
  layer.addEventListener('touchend', end, { passive: true });
  layer.addEventListener('touchcancel', end, { passive: true });

  window.ness = {
    write: function (s) { term.write(sanitize(s), function () { post({ t: 'ack' }); }); },
    focus: function () { input.focus({ preventScroll: true }); },
    blur: function () { input.blur(); },
    paste: function (s) { term.paste(s); },
    scrollToBottom: function () { cancelAnimationFrame(raf); term.scrollToBottom(); reportScroll(); }
  };
  tryReady();
})();
`

export function terminalPageHtml(opts: TerminalPageOptions): string {
  return `<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<style>${XTERM_CSS}</style>
<style>
html,body{margin:0;padding:0;height:100%;overflow:hidden;background:${opts.theme.background};-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
#term{position:absolute;inset:0 0 0 4px}
.xterm-viewport{overflow-y:hidden!important}
.xterm{font-variant-emoji:text}
#touch{position:absolute;inset:0;z-index:10;touch-action:none}
#input{position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;border:0;padding:0;font-size:16px;resize:none;caret-color:transparent}
</style></head><body>
<div id="term"></div><div id="touch"></div>
<textarea id="input" autocapitalize="off" autocorrect="off" autocomplete="off" spellcheck="false" aria-label="Terminal input"></textarea>
<script>window.__NESS_OPTS=${JSON.stringify(opts).replace(/</g, '\\u003c')}</script>
<script>${XTERM_JS}</script>
<script>${FIT_JS}</script>
<script>${BRIDGE}</script>
</body></html>`
}
